mapper.select:
        SELECT
            vch.*,
            vcg.id as group_id,
            vcg.name as group_name,
            vp.id as panel_id,
            vp.name as panel_name,
            case when vch.var_type=1 then aa.name when vch.var_type=2 then me.name end as var_name
        FROM visual_chart vch
        left join visual_chart vcg on vch.group_id = vcg.id
		left join visual_panel vp on vch.panel_id = vp.id
		left join asset_asset aa on vch.var_id = aa.id 
		left join monitor_endpoint me on vch.var_id = me.id 
        WHERE 1=1

            and vch.id in 

	       		#{id}




            AND vch.panel_id = #{params.panelId}



            AND vch.name LIKE CONCAT('%', #{params.name}, '%')



            AND vch.type = #{params.type}



            AND vch.pid in 

		       		#{pid}




            AND vch.var_type = #{params.varType}



			AND vch.group_id = #{params.groupId}



			AND vch.group_id in 

		       		#{gid}



        /* 如果排序字段为null , 按照 weight 排序 */

            ORDER BY vch.weight,vch.id

